    junction_type = EXCLUDED.junction_type, signal_control = EXCLUDED.signal_control,
    geom = EXCLUDED.geom, name = EXCLUDED.name, name_bn = EXCLUDED.name_bn,
    osm_node_id = EXCLUDED.osm_node_id
WHERE j.junction_type IS DISTINCT FROM EXCLUDED.junction_type
   OR j.signal_control IS DISTINCT FROM EXCLUDED.signal_control
   OR NOT ST_OrderingEquals(j.geom, EXCLUDED.geom)
   OR j.name IS DISTINCT FROM EXCLUDED.name
   OR j.name_bn IS DISTINCT FROM EXCLUDED.name_bn
   OR j.osm_node_id IS DISTINCT FROM EXCLUDED.osm_node_id;

SELECT setval(pg_get_serial_sequence('corridor.junctions', 'junction_id'),
              GREATEST((SELECT max(junction_id) FROM corridor.junctions), 1));

