DELETE FROM corridor.segment_adjacency sa
WHERE NOT EXISTS (
    SELECT 1 FROM _sahoshi_osm_moves m
    WHERE m.from_segment_id = sa.from_segment_id
      AND m.to_segment_id = sa.to_segment_id
      AND m.via_junction_id = sa.via_junction_id
);

INSERT INTO corridor.segment_adjacency AS sa (from_segment_id, to_segment_id,
    via_junction_id, turn_cost_sec)
SELECT from_segment_id, to_segment_id, via_junction_id, turn_cost_sec FROM _sahoshi_osm_moves
ON CONFLICT (from_segment_id, to_segment_id, via_junction_id) DO UPDATE SET
    turn_cost_sec = EXCLUDED.turn_cost_sec
WHERE sa.turn_cost_sec IS DISTINCT FROM EXCLUDED.turn_cost_sec;

-- =============================================================================
-- D. SIGNAL PROGRAMS (source osm_assumed only — a calibrated row is kept)
-- =============================================================================

INSERT INTO corridor.signal_programs AS p (junction_id, cycle_sec, phases, offset_sec, source)
VALUES
    (12, 110, '[{"green_sec": 50, "movements": ["through"]}, {"green_sec": 42, "movements": ["cross"]}]'::jsonb, 94, 'osm_assumed'),
    (14, 110, '[{"green_sec": 50, "movements": ["through"]}, {"green_sec": 42, "movements": ["cross"]}]'::jsonb, 18, 'osm_assumed'),
    (18, 110, '[{"green_sec": 50, "movements": ["through"]}, {"green_sec": 42, "movements": ["cross"]}]'::jsonb, 86, 'osm_assumed'),
    (19, 110, '[{"green_sec": 50, "movements": ["through"]}, {"green_sec": 42, "movements": ["cross"]}]'::jsonb, 103, 'osm_assumed'),
    (20, 110, '[{"green_sec": 50, "movements": ["through"]}, {"green_sec": 42, "movements": ["cross"]}]'::jsonb, 10, 'osm_assumed'),
    (33, 110, '[{"green_sec": 50, "movements": ["through"]}, {"green_sec": 42, "movements": ["cross"]}]'::jsonb, 11, 'osm_assumed')
ON CONFLICT (junction_id) DO UPDATE SET
    cycle_sec = EXCLUDED.cycle_sec, phases = EXCLUDED.phases,
    offset_sec = EXCLUDED.offset_sec, updated_at = NOW()
WHERE p.source = 'osm_assumed'
  AND (p.cycle_sec IS DISTINCT FROM EXCLUDED.cycle_sec
       OR p.phases IS DISTINCT FROM EXCLUDED.phases
       OR p.offset_sec IS DISTINCT FROM EXCLUDED.offset_sec);

DELETE FROM corridor.signal_programs p
USING corridor.junctions j
WHERE j.junction_id = p.junction_id
  AND p.source = 'osm_assumed'
  AND NOT COALESCE(j.signal_control, FALSE)
  AND NOT EXISTS (SELECT 1 FROM corridor.signal_program_history h
                  WHERE h.junction_id = p.junction_id);

-- =============================================================================
-- E. CAMERA SITES — source emulated (EMULATED badge); locations only, no
-- frames, no images (C6).  A stop-line site sits 25 m back along its
-- approach (further where a slip another segment shares runs there: up to
-- 38 m for ANPR, inside the e-challan engine's 40 m junction radius) and reads
-- traffic heading INTO the junction; a bridge-head site sits 15 % into the
-- bridge span from its landing, reading traffic heading onto the bridge; a
-- watchlist sweep camera (EM-CAM-0n) is the point ON its segment nearest the
-- segment's centroid (the emulator's anchor for it).  An operator's status
-- (offline, maintenance) is kept.
-- =============================================================================

