    ('CV-SHYAMBAZAR', 'jan_rakshak', 'jr_post', 'Civic Volunteer Post - Shyambazar (emulated)', 'সিভিক ভলান্টিয়ার পোস্ট - শ্যামবাজার (এমুলেটেড)',
     ST_GeomFromText('POINT(88.3732000 22.6015000)', 4326), 'emulated', NULL),
    ('CV-GARIAHAT', 'jan_rakshak', 'jr_post', 'Civic Volunteer Post - Gariahat (emulated)', 'সিভিক ভলান্টিয়ার পোস্ট - গড়িয়াহাট (এমুলেটেড)',
     ST_GeomFromText('POINT(88.3650000 22.5194000)', 4326), 'emulated', NULL),
    ('EMS-108-SSKM', 'ambulance', 'ems_base', 'Ambulance (108) Base - SSKM (emulated)', 'অ্যাম্বুলেন্স (১০৮) বেস - এসএসকেএম (এমুলেটেড)',
     ST_GeomFromText('POINT(88.3440000 22.5390000)', 4326), 'emulated', NULL),
    ('EMS-108-SALT-LAKE', 'ambulance', 'ems_base', 'Ambulance (108) Base - Salt Lake (emulated)', 'অ্যাম্বুলেন্স (১০৮) বেস - সল্টলেক (এমুলেটেড)',
     ST_GeomFromText('POINT(88.4095000 22.5700000)', 4326), 'emulated', NULL),
    ('TP-PARK-CIRCUS', 'traffic', 'police_station', 'Traffic Police Kiosk - Park Circus (emulated)', 'ট্রাফিক পুলিশ কিয়স্ক - পার্ক সার্কাস (এমুলেটেড)',
     ST_GeomFromText('POINT(88.3656000 22.5427000)', 4326), 'emulated', NULL)
ON CONFLICT (station_id) DO UPDATE SET
    agency = EXCLUDED.agency, kind = EXCLUDED.kind, name = EXCLUDED.name,
    name_bn = EXCLUDED.name_bn, geom = EXCLUDED.geom, source = EXCLUDED.source,
    osm_ref = EXCLUDED.osm_ref, updated_at = NOW()
WHERE st.agency IS DISTINCT FROM EXCLUDED.agency
   OR st.kind IS DISTINCT FROM EXCLUDED.kind
   OR st.name IS DISTINCT FROM EXCLUDED.name
   OR st.name_bn IS DISTINCT FROM EXCLUDED.name_bn
   OR NOT ST_OrderingEquals(st.geom, EXCLUDED.geom)
   OR st.source IS DISTINCT FROM EXCLUDED.source
   OR st.osm_ref IS DISTINCT FROM EXCLUDED.osm_ref;

-- =============================================================================
-- G. PROVENANCE — the original seed wrote random numbers into the REAL-only
-- traffic.hourly_aggregates (migration 019), stamped date_trunc('hour', NOW())
-- of the seed load, which is also every seeded segment's created_at.  Only
-- that hour bucket is touched (the bucket starting within the hour before the
-- seed load, whatever the seed session's time zone), and a row survives when
-- a data_quality = 'real' observation of its segment exists in its hour.
-- =============================================================================

DELETE FROM traffic.hourly_aggregates h
WHERE h.hour_utc <= (SELECT min(created_at) FROM corridor.road_segments)
  AND h.hour_utc > (SELECT min(created_at) FROM corridor.road_segments) - interval '1 hour'
  AND NOT EXISTS (
      SELECT 1 FROM traffic.observations o
      WHERE o.segment_id = h.segment_id
        AND o.data_quality = 'real'
        AND o.timestamp_utc >= h.hour_utc
        AND o.timestamp_utc < h.hour_utc + interval '1 hour'
  );

-- =============================================================================
-- H. EVENT-PROFILE SPINES — events.event_profiles holds each use case's
-- representative route (migrations 008 / 010), drawn on the schematic
-- network: most are no longer paths on the real one.  A profile whose spine
-- is STILL the seeded value takes the route the use-case library runs on this
-- network (services/event-emulator/src/event_emulator/use_case_library.json,
-- which scripts/scenario_library.json agrees with) — every one a legal
-- directed path, the one-ways included (the generator checks).  A spine an
-- operator changed is kept.  Events already instantiated from a profile
-- (events.event_routes) are recorded history and are not rewritten.
-- Profiles already on their library route are not listed.
-- =============================================================================

UPDATE events.event_profiles AS p
SET route_segment_ids = v.spine
FROM (VALUES
    ('cloudburst_high_tide', ARRAY[1035, 1036, 1037, 1038]::BIGINT[], ARRAY[1039, 1062, 1058]::BIGINT[]),
    ('durga_puja_north', ARRAY[1060, 1057, 1059, 1052]::BIGINT[], ARRAY[1061, 1060, 1058]::BIGINT[]),
    ('gangasagar_transit', ARRAY[1001, 1004, 1005]::BIGINT[], ARRAY[1001, 1004, 1005, 1006, 1047, 1048]::BIGINT[]),
    ('watchlist_anpr_sweep', ARRAY[1001, 1008, 1009, 1010]::BIGINT[], ARRAY[1001, 1004, 1012, 1010, 1016, 1051, 1054, 1008]::BIGINT[])
) AS v (profile_id, seeded, spine)
WHERE p.profile_id = v.profile_id
  AND p.route_segment_ids = v.seeded
  AND p.route_segment_ids IS DISTINCT FROM v.spine;

-- =============================================================================
-- I. EVENT-PROFILE TEXT — a profile column still at the value its migration
-- seeded, where that value promises what the emulator does not do, takes the
-- honest text (the pack's profile_text_fixes).  Data hygiene: nothing reads
-- these columns at run time.  A column an operator changed is kept, and a
-- second apply changes nothing.
-- Every corrected text already equals its seeded value: nothing to do.
-- =============================================================================

COMMIT;
